class Solution {
public:
    vector<vector<int>> res;
    vector<int> path;
    void go(int start, int remain, int k) {
        if ((int)path.size() == k) {
            if (remain == 0) res.push_back(path);
            return;
        }
        for (int x = start; x <= 9 && x <= remain; x++) {
            path.push_back(x);
            go(x + 1, remain - x, k);
            path.pop_back();
        }
    }
    vector<vector<int>> combinationSum3(int k, int n) {
        go(1, n, k);
        return res;
    }
};
